head.script:
//
(function () {
  var repo = 'venkateshramu07-design/My_Repo', ver = 'e563f998ef7a3942dd1fc330a697b786438e8cf1', c = null, now = Date.now();
  try { c = JSON.parse(localStorage.getItem('bd-ver2') || 'null'); } catch (e) {}
  if (c && now - c.t < 6e5) ver = c.v;
  else {
    try {
      var x = new XMLHttpRequest();
      x.open('GET', 'https://raw.githubusercontent.com/' + repo + '/ccr-ee047f91-rbyv4x/seo/theme/version.txt', false);
      x.send();
      var t = (x.responseText || '').trim();
      if (x.status === 200 && /^[0-9a-f]{40}$/.test(t)) { ver = t; localStorage.setItem('bd-ver2', JSON.stringify({ v: t, t: now })); }
      else if (c) ver = c.v;
    } catch (e) { if (c) ver = c.v; }
  }
  document.write('<script src="https://cdn.jsdelivr.net/gh/' + repo + '@' + ver + '/seo/theme/bd-redesign.js"><\/script>');
})();
//

head.b:skin:
/* 
-----------------------------------------------
Blogger Template Style
Name:        Sora24
License:     Free Version
Version:     2.0
Author:      Sora Templates
Author Url:  https://www.soratemplates.com/
----------------------------------------------- */

/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="$(main.color)" value="#ec0000"/>
<Variable name="followByEmail" description="Follow By Email Text" type="string" default="Get all latest content delivered straight to your inbox." value="Get all latest content delivered straight to your inbox."/>

<Group description="Theme Colors" selector="body">
 <Variable name="main.color" description="Theme Color" type="color" default="#ff749f" value="#ec0000"/>
  <Variable name="main.dark.color" description="Dark Color" type="color" default="#202020" value="#000000"/>
  <Variable name="menu.color" description="Menu Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="title.color" description="Title Color" type="color" default="#333333" value="#000000"/>
  <Variable name="title.hover" description="Title Color on Hover" type="color" default="$(main.color)" value="#ff0000"/>
  <Variable name="footer.color" description="Footer Color" type="color" default="#f1ffff" value="#ebf9ff"/>
</Group>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body Background Color" type="color" default="#f8f8f8"  value="#f5f5f5"/>
  <Variable name="body.background" description="Background" type="background" color="$(body.background.color)" default="$(color) url() repeat fixed top left" value="$(color) url() repeat fixed top left"/>
  <Variable name="body.text.color" description="Text Color" type="color" default="#656565"  value="#4e4e4e"/>
  <Variable name="body.link.color" description="Link Color" type="color" default="$(main.color)"  value="#ec0000"/>
</Group>

<!-- Extra Variables -->
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="13px Poppins, sans-serif"  value="13px Poppins, sans-serif"/>
<Variable name="posts.background.color" description="Post background color" hideEditor="true" type="color" default="#ffffff"  value="#ffffff"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="13px Poppins, sans-serif"  value="13px Poppins, sans-serif"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="#333333"  value="#000000"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="#656565"  value="#4e4e4e"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)"  value="#ff749f"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="$(main.color)"  value="#ff749f"/>
*/

/*-- Reset CSS --*/
 .CSS_LIGHTBOX{z-index:999999!important}.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER > .CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child > .CSS_LAYOUT_COMPONENT{opacity:0}#google_translate_element { clear: both; }.thread-expanded .thread-count a { display: none; }.comments .continue { display: none!important; } a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{
    padding:0;
    border:0;
    outline:0;
    vertical-align:baseline;
    background:0 0;
    text-decoration:none
}
form,textarea,input,button{
    -webkit-appearance:none;
    -moz-appearance:none;
    appearance:none;
    border-radius:0
}
dl,ul{
    list-style-position:inside;
    font-weight:400;
    list-style:none
}
ul li{
    list-style:none
}
caption,th{
    text-align:center
}
img{
    border:none;
    position:relative
}
a,a:visited{
    text-decoration:none
}
.clearfix{
    clear:both
}
.section,.widget,.widget ul{
    margin:0;
    padding:0
}
a{
    color:$(body.link.color)
}
a img{
    border:0
}
abbr{
    text-decoration:none
}
.CSS_LIGHTBOX{
    z-index:999999!important
}
.separator a{
    clear:none!important;
    float:none!important;
    margin-left:0!important;
    margin-right:0!important
}
#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{
    display:none!important
}
.center{
    display:table;
    margin:0 auto;
    position:relative
}
.widget > h2,.widget > h3{
    display:none
}
/*-- Body Content CSS --*/
 body{
    background:$(body.background);
    background-color:$(body.background.color);
    font-family: 'Open Sans', sans-serif;
    font-size:14px;
    font-weight:400;
    color:$(body.text.color);
    word-wrap:break-word;
    margin:0;
    padding:0
}


/* ######## Top Css ######################### */


#outer-wrapper{margin:0 auto;background-color:#fff;box-shadow:0 0 5px rgba(0,0,0,.1)}
.row{margin:0 auto;width:1140px}
#content-wrapper{margin: 20px auto 0px;overflow:hidden}
#content-wrapper > .container{margin:0 -15px}
#main-wrapper{float:left;overflow:hidden;width:66.66666667%;box-sizing:border-box;word-wrap:break-word;padding:0 15px;margin:0}
#sidebar-wrapper{float:right;overflow:hidden;width:33.33333333%;box-sizing:border-box;word-wrap:break-word;padding:0 15px}
.post-image-wrap{position:relative;display:block}
.post-image-link,.about-author .avatar-container,.comments .avatar-image-container{background-color:rgba(155,155,155,0.07);color:transparent!important}
.post-thumb{  display:block;
    position:relative;
    width:100%;
    height:100%;
   object-fit:cover;
    object-position: top;
    z-index:1;
    opacity: 0;
    transition:opacity .17s ease}
.post-thumb.lazy-yard {
    opacity: 1;
}
.post-image-link:hover .post-thumb,.post-image-wrap:hover .post-image-link .post-thumb,.hot-item-inner:hover .post-image-link .post-thumb{opacity:.9}
.post-title a{display:block}
#top-bar{width:100%;height:42px;background-color:#fff;overflow:hidden;margin:0;border-bottom:1px solid #eee}
#top-bar .container{margin:0 auto}
.top-bar-nav{position:relative;float:left;display:block}
.top-bar-nav .widget > .widget-title{display:none}
.top-bar-nav ul li{float:left}
.top-bar-nav ul li > a{letter-spacing:.2px;height:42px;display:block;color:#1c1c1c;font-size:13px;font-weight:600;line-height:42px;text-transform:capitalize;margin:0 10px 0 0;padding:0 5px;transition:color .17s}
.top-bar-nav ul li:first-child > a{padding:0 5px 0 0}
.top-bar-nav ul > li:hover > a{color:$(title.color)}
.top-bar-social{position:relative;float:right;display:block}
.top-bar-social .widget > .widget-title{display:none}
.top-bar-social ul > li{float:left;display:inline-block}
.top-bar-social ul > li > a{line-height:42px;display:block;color:#1c1c1c;text-decoration:none;font-size:14px;text-align:center;padding:0 7px;margin:0 0 0 10px;transition:color .17s}
.top-bar-social ul > li:last-child > a{padding:0 0 0 7px}
.top-bar-social ul > li:hover > a{color:$(title.color)}
.social a:before{display:inline-block;font-family:FontAwesome;font-style:normal;font-weight:400}
.social .blogger a:before{content:"\f37d"}
.social .facebook a:before{content:"\f09a"}
.social .twitter a:before{content:"\f099"}
.social .gplus a:before{content:"\f0d5"}
.social .rss a:before{content:"\f09e"}
.social .youtube a:before{content:"\f167"}
.social .skype a:before{content:"\f17e"}
.social .stumbleupon a:before{content:"\f1a4"}
.social .tumblr a:before{content:"\f173"}
.social .vk a:before{content:"\f189"}
.social .stack-overflow a:before{content:"\f16c"}
.social .github a:before{content:"\f09b"}
.social .linkedin a:before{content:"\f0e1"}
.social .dribbble a:before{content:"\f17d"}
.social .soundcloud a:before{content:"\f1be"}
.social .behance a:before{content:"\f1b4"}
.social .digg a:before{content:"\f1a6"}
.social .instagram a:before{content:"\f16d"}
.social .pinterest a:before{content:"\f0d2"}
.social .twitch a:before{content:"\f1e8"}
.social .delicious a:before{content:"\f1a5"}
.social .codepen a:before{content:"\f1cb"}
.social .reddit a:before{content:"\f1a1"}
.social .whatsapp a:before{content:"\f232"}
.social .snapchat a:before{content:"\f2ac"}
.social .email a:before{content:"\f0e0"}
.social .external-link a:before{content:"\f35d"}
.social-color .blogger a{background-color:#ff5722}
.social-color .facebook a{background-color:#3b5999}
.social-color .twitter a{background-color:#00acee}
.social-color .gplus a{background-color:#db4a39}
.social-color .youtube a{background-color:#f50000}
.social-color .instagram a{background:linear-gradient(15deg,#ffb13d,#dd277b,#4d5ed4)}
.social-color .pinterest a{background-color:#ca2127}
.social-color .dribbble a{background-color:#ea4c89}
.social-color .linkedin a{background-color:#0077b5}
.social-color .tumblr a{background-color:#365069}
.social-color .twitch a{background-color:#6441a5}
.social-color .rss a{background-color:#ffc200}
.social-color .skype a{background-color:#00aff0}
.social-color .stumbleupon a{background-color:#eb4823}
.social-color .vk a{background-color:#4a76a8}
.social-color .stack-overflow a{background-color:#f48024}
.social-color .github a{background-color:#24292e}
.social-color .soundcloud a{background:linear-gradient(#ff7400,#ff3400)}
.social-color .behance a{background-color:#191919}
.social-color .digg a{background-color:#1b1a19}
.social-color .delicious a{background-color:#0076e8}
.social-color .codepen a{background-color:#000}
.social-color .reddit a{background-color:#ff4500}
.social-color .whatsapp a{background-color:#3fbb50}
.social-color .snapchat a{background-color:#ffe700}
.social-color .email a{background-color:#888}
.social-color .external-link a{background-color:$(main.dark.color)}
#header-wrap{position:relative;margin:0}
.header-header{background-color:#fff;width:100%;height:70px;position:relative;padding:8px 0}
.header-header .container{border-bottom:1px solid #e7e7e7;height:70px;position:relative;margin:0 auto;padding:0}
.header-logo{position:relative;float:left;width:auto;max-width:250px;max-height:60px;margin:0;padding:12px 0}
.header-logo .header-image-wrapper{display:block}
.header-logo img{max-width:100%;max-height:60px;margin:0}
.header-logo h1{color:$(title.color);font-size:20px;line-height:1.4em;margin:0}
.header-logo p{font-size:12px;margin:5px 0 0}
.header-ads{position:relative;float:right}
.header-ads .widget > .widget-title{display:none}
.header-ads .widget{max-width:100%}
.header-ads .widget .widget-content{width:728px;max-width:100%;max-height:90px;line-height:1}



/* ######## Main-Menu Css ######################### */


.header-menu{display:inline-block;float:right;height:70px;z-index:10;font-size:13px;margin:0}
.header-menu .container{position:relative;margin:0 auto;padding:0;background-color:$(main.color)}
#main-menu .widget,#main-menu .widget > .widget-title{display:none}
#main-menu .show-menu{display:block}
#main-menu{height:70px;z-index:15}
#main-menu ul > li{float:left;position:relative;margin:0;padding:0;transition:background .17s}
#main-menu ul > li > a{position:relative;color:#000;font-size:14px;font-weight:700;text-transform:uppercase;line-height:70px;display:inline-block;margin:0;padding:0 13px;transition:color .17s ease}
#main-menu ul > li:last-child a{padding-right:0}
#main-menu ul#main-menu-nav > li:first-child > a{color:$(main.color)}
h3.home-title{font-family:'Arimo',sans-serif;text-transform:uppercase;font-size:14px;height:34px;margin:0 0 20px;line-height:34px;border-bottom:2px solid #1c1c1c;letter-spacing:.2px}
h3.home-title span{position:relative;background:#000;color:#fff;padding:10px 15px}
h3.home-title span:after{border-color:#272727 rgba(0,0,0,0) rgba(0,0,0,0);position:absolute;content:" ";width:auto;height:auto;bottom:-20px;margin-left:-10px;left:50%;border-width:10px;border-style:solid}
#main-menu ul > li > ul{position:absolute;float:left;left:0;top:70px;width:180px;background-color:#fff;z-index:99999;margin:0;padding:0;box-shadow:0 3px 5px rgba(0,0,0,0.2);visibility:hidden;opacity:0}
#main-menu ul > li > ul > li > ul{position:absolute;float:left;top:0;left:100%;margin:0}
#main-menu ul > li > ul > li{display:block;float:none;position:relative;transition:all .17s ease}
#main-menu ul > li > ul > li a{display:block;height:36px;font-size:12px;color:#282828;line-height:36px;box-sizing:border-box;margin:0;padding:0 15px;transition:all .17s ease}
#main-menu ul > li > ul > li:hover{background-color:$(main.color)}
#main-menu ul > li > ul > li:hover > a{color:#fff}
#main-menu ul > li.has-sub > a:after{content:'\f107';float:right;font-family:FontAwesome;font-size:14px;font-weight:400;margin:0 0 0 3px}
#main-menu ul > li > ul > li.has-sub > a:after{content:'\f105';float:right;margin:0}
#main-menu .mega-menu{position:static!important}
#main-menu .mega-menu > ul{width:100%;box-sizing:border-box;padding:20px 10px}
#main-menu .mega-menu > ul.mega-menu-inner{overflow:hidden}
#main-menu ul > li:hover > ul,#main-menu ul > li > ul > li:hover > ul{visibility:visible;opacity:1}
#main-menu ul ul{transition:all .17s ease}
.mega-menu-inner .mega-item{float:left;width:25%;box-sizing:border-box;padding:0 10px}
.mega-menu-inner .mega-content{position:relative;width:100%;overflow:hidden;padding:0}
.mega-content .post-image-wrap{width:100%;height:140px;overflow:hidden}
.mega-content .post-image-link{width:100%;height:100%;z-index:1;display:block;position:relative;overflow:hidden}
.mega-content .post-title{position:relative;font-size:14px;font-weight:600;line-height:1.4em;margin:7px 0 5px}
.mega-content .post-title a{display:block;color:#282828;transition:color .17s}
.mega-content:hover .post-title a{color:$(title.hover)}
.mega-content .post-meta{color:#aaa}
.no-posts{float:left;width:100%;height:100px;line-height:100px;text-align:center}
.mega-menu .no-posts{line-height:60px;color:$(title.color)}
.show-search,.hide-search{position:absolute;right:0;top:0;display:block;width:48px;height:48px;line-height:48px;z-index:20;color:$(menu.color);font-size:15px;text-align:center;cursor:pointer;transition:color .17s ease}
.show-search:before{content:"\f002";font-family:FontAwesome;font-weight:400}
.hide-search:before{content:"\f00d";font-family:FontAwesome;font-weight:400}
.show-search:hover,.hide-search:hover{color:#fff}
#nav-search{display:none;position:absolute;left:0;top:0;width:100%;height:48px;z-index:99;background-color:$(main.color);box-sizing:border-box;padding:0}
#nav-search .search-form{width:100%;height:48px;background-color:rgba(0,0,0,0);line-height:48px;overflow:hidden;padding:0}
#nav-search .search-input{width:100%;height:48px;font-family:inherit;color:$(menu.color);margin:0;padding:0 70px 0 15px;background-color:rgba(0,0,0,0);font-size:14px;font-weight:400;box-sizing:border-box;border:0}
#nav-search .search-input:focus{color:$(menu.color);outline:none}
.slide-menu-toggle{display:none;position:absolute;line-height:48px;height:48px;width:48px;top:0;left:0;font-family:FontAwesome;color:#fff;font-size:17px;font-weight:400;text-align:left;cursor:pointer;z-index:4;padding:0}
.slide-menu-toggle:before{content:"\f0c9"}
.nav-active .slide-menu-toggle:before{content:"\f00d"}
.mobile-menu{display:none;position:absolute;top:48px;left:0;width:100%;background-color:$(main.dark.color);box-sizing:border-box;padding:20px;border-top:1px solid rgba(255,255,255,0.08);visibility:hidden;opacity:0;transform-origin:0 0;transform:scaleY(0);transition:all .17s ease}
.nav-active .mobile-menu{visibility:visible;opacity:1;transform:scaleY(1)}
.mobile-menu > ul{margin:0}
.mobile-menu .m-sub{display:none;padding:0}
.mobile-menu ul li{position:relative;display:block;overflow:hidden;float:left;width:100%;font-size:13px;font-weight:500;text-transform:uppercase;line-height:38px;margin:0;padding:0}
.mobile-menu > ul li ul{overflow:hidden}
.mobile-menu ul li a{color:#fff;padding:0;display:block;transition:all .17s ease}
.mobile-menu ul li.has-sub .submenu-toggle{position:absolute;top:0;right:0;color:#fff;cursor:pointer}
.mobile-menu ul li.has-sub .submenu-toggle:after{content:'\f105';font-family:FontAwesome;font-weight:400;float:right;width:34px;font-size:16px;text-align:center;transition:all .17s ease}
.mobile-menu ul li.has-sub.show > .submenu-toggle:after{transform:rotate(90deg)}
.mobile-menu > ul > li > ul > li > a{color:#fff;opacity:.7;padding:0 0 0 15px}
.mobile-menu > ul > li > ul > li > ul > li > a{color:#fff;opacity:.7;padding:0 0 0 30px}
.mobile-menu ul li a:hover,.mobile-menu ul > li > .submenu-toggle:hover{color:$(main.color)}


/* ######## Post-Meta Css ######################### */


.post-meta{overflow:hidden;color:$(main.color);font-size:12px;font-weight:500;text-transform:capitalize;padding:0 1px}
.post-meta .post-author,.post-meta .post-date{color:#888;float:left;display:inline-block;margin:0 10px 0 0}
.post-meta .post-author:before,.post-meta .post-date:before{font-family:FontAwesome;font-weight:400;margin:0 3px 0 0}
.post-meta .post-author:before{content:'\f007'}
.post-meta .post-date:before{content:'\f017'}
.post-meta a{color:#1c1c1c;transition:color .17s;font-weight:700}
.post-meta a:hover{color:$(title.color)}


/* ######## Blog-Page Css ######################### */


#blog-pager{overflow:hidden;clear:both;margin:0 0 30px}
.blog-pager a,.blog-pager span{float:left;display:block;min-width:30px;height:30px;background-color:$(main.dark.color);color:#fff;font-size:13px;font-weight:700;line-height:30px;text-align:center;box-sizing:border-box;margin:0 5px 0 0;text-shadow:1px 2px 0 rgba(0,0,0,0.15);transition:all .17s ease}
.blog-pager .blog-pager-newer-link,.blog-pager .blog-pager-older-link{padding:0 15px}
.blog-pager .blog-pager-newer-link{float:left}
.blog-pager .blog-pager-older-link{float:right}
.blog-pager span.page-dots{min-width:20px;background-color:#fff;font-size:16px;color:$(title.color);line-height:30px;font-weight:400;letter-spacing:-1px;border:0}
.blog-pager .page-of{display:none;width:auto;float:right;border-color:rgba(0,0,0,0);margin:0}
.blog-pager .page-active,.blog-pager a:hover{background-color:$(main.color);color:#fff}
.blog-pager .page-prev:before,.blog-pager .page-next:before{font-family:FontAwesome;font-size:16px;font-weight:400}
.blog-pager .page-prev:before{content:'\f104'}
.blog-pager .page-next:before{content:'\f105'}
.blog-pager .blog-pager-newer-link:after{content:'\f104';float:left;font-family:FontAwesome;font-weight:400;margin:0 3px 0 0}
.blog-pager .blog-pager-older-link:after{content:'\f105';float:right;font-family:FontAwesome;font-weight:400;margin:0 0 0 3px}
.archive #blog-pager{display:none}


/* ######## Social Css ######################### */

.social-counter .facebook a{background-color:#3b5999}
.social-counter .twitter a{background-color:#00acee}
.social-counter .gplus a{background-color:#db4a39}
.social-counter .youtube a{background-color:#f50000}
.social-counter .instagram a{background:linear-gradient(15deg,#ffb13d,#dd277b,#4d5ed4)}
.social-counter .pinterest a{background-color:#ca2127}
.social-counter .dribbble a{background-color:#ea4c89}
.social-counter .linkedin a{background-color:#0077b5}
.social-counter .tumblr a{background-color:#365069}
.social-counter .twitch a{background-color:#6441a5}
.social-counter .rss a{background-color:#ffc200}
.social-counter .skype a{background-color:#00aff0}
.social-counter .stumbleupon a{background-color:#eb4823}
.social-counter .vk a{background-color:#4a76a8}
.social-counter .stack-overflow a{background-color:#f48024}
.social-counter .github a{background-color:#24292e}
.social-counter .soundcloud a{background:linear-gradient(#ff7400,#ff3400)}
.social-counter .behance a{background-color:#191919}
.social-counter .digg a{background-color:#1b1a19}
.social-counter .delicious a{background-color:#0076e8}
.social-counter .codepen a{background-color:#000}
.social-counter .reddit a{background-color:#ff4500}
.social-counter .whatsapp a{background-color:#3fbb50}
.social-counter .snapchat a{background-color:#ffe700}
.social-counter .email a{background-color:#888}
.social-counter .external-link a{background-color:#202020}


/* ######## Lower Css ######################### */

.lower-menu{float:right}
.lower-menu ul li{display:inline-block}
.lower-menu ul li a{letter-spacing:.2px;font-family:'Arimo',sans-serif;color:#fff;padding:0 6px;height:34px;line-height:34px;display:block;font-size:13px}
.lower-menu ul li:last-child a{padding-right:0}


/* ######## Owl-carousel Css ######################### */



.owl-carousel{display:none;width:100%;-webkit-tap-highlight-color:transparent;position:relative;z-index:1}
.owl-carousel .owl-stage{position:relative;-ms-touch-action:pan-Y}
.owl-carousel .owl-stage:after{content:".";display:block;clear:both;visibility:hidden;line-height:0;height:0}
.owl-carousel .owl-stage-outer{position:relative;overflow:hidden;-webkit-transform:translate3d(0px,0px,0px)}
.owl-carousel .owl-controls .owl-nav .owl-prev,.owl-carousel .owl-controls .owl-nav .owl-next,.owl-carousel .owl-controls .owl-dot{cursor:pointer;cursor:hand;-webkit-user-select:none;-khtml-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none}
.owl-carousel.owl-loaded{display:block}
.owl-carousel.owl-loading{opacity:0;display:block}
.owl-carousel.owl-hidden{opacity:0}
.owl-carousel .owl-refresh .owl-item{display:none}
.owl-carousel .owl-item{position:relative;min-height:1px;float:left;-webkit-backface-visibility:visible;-webkit-tap-highlight-color:transparent;-webkit-touch-callout:none;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none}
.owl-carousel .owl-item img{display:block;width:100%;-webkit-transform-style:preserve-3d;transform-style:preserve-3d}
.owl-carousel.owl-text-select-on .owl-item{-webkit-user-select:auto;-moz-user-select:auto;-ms-user-select:auto;user-select:auto}
.owl-carousel .owl-grab{cursor:move;cursor:-webkit-grab;cursor:-o-grab;cursor:-ms-grab;cursor:grab}
.owl-carousel.owl-rtl{direction:rtl}
.owl-carousel.owl-rtl .owl-item{float:right}
.no-js .owl-carousel{display:block}
.owl-carousel .animated{-webkit-animation-duration:1000ms;animation-duration:1000ms;-webkit-animation-fill-mode:both;animation-fill-mode:both}
.owl-carousel .owl-animated-in{z-index:1}
.owl-carousel .owl-animated-out{z-index:0}
.owl-height{-webkit-transition:height 500ms ease-in-out;-moz-transition:height 500ms ease-in-out;-ms-transition:height 500ms ease-in-out;-o-transition:height 500ms ease-in-out;transition:height 500ms ease-in-out}
.owl-prev,.owl-next{position:relative;float:left;width:24px;height:24px;background-color:$(main.color);font-family:FontAwesome;text-rendering:auto;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;font-size:14px;line-height:23px;font-weight:900;color:#fff;text-align:center;cursor:pointer;border:1px solid rgba(0,0,0,0.08);box-sizing:border-box;transition:all .25s ease}
.owl-prev:before{content:'\f104'}
.owl-next:before{content:'\f105'}
.owl-prev:hover,.owl-next:hover{background-color:$(main.color);color:#fff;border-color:$(main.color)}
#break-wrapper{padding:10px 0px;background-color:#f5f5f5;box-sizing:border-box}
#break-section .widget{display:none;}
#break-section .widget.HTML.show-ticker{display:block;margin:0}
ul.loading-post{line-height:30px;margin-left:10px}
#break-section .no-posts{height:30px;line-height:30px;text-align:left;padding:0 0 0 15px;box-sizing:border-box}
#break-section .widget > .widget-title{display:none;position:relative;float:left;background-color:$(main.color);height:24px;color:#fff;font-size:9px;font-weight:400;line-height:24px;text-transform:uppercase;padding:0 10px}
#break-section .show-ticker > .widget-title{display:block}
#break-section .widget > h2,#break-section .widget > h3{display:none}
#break-section .widget > .widget-title > h3{margin:0;position:relative}
#break-section .widget > .widget-title > h3:before{content:'\f0e7';font-family:FontAwesome;float:left;font-size:11px;font-weight:900;margin:0 5px 0 0;text-rendering:auto;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
#break-section .widget-content{position:relative;font-size:13px;display:block;overflow:hidden;height:30px;line-height:29px;padding:0;box-sizing:border-box}
ul.ticker-widget{width:100%!important;box-sizing:border-box;padding:0 0 0 15px}
.ticker-widget .ticker-item{position:relative;float:left;display:block;height:30px;padding:0}
.ticker-widget .post-image-link{position:relative;float:left;width:35px;height:30px;display:none;overflow:hidden;margin:0 10px 0 0}
.ticker-widget .post-title{
    font-family: 'Arimo', sans-serif;
    height: 18px;
    font-size: 15px;
    font-weight: 600;
    line-height: 24px;
    margin: 0;
    padding: 0;
    float: left;
}
.ticker-widget .post-title a{position:relative;display:block;overflow:hidden;color:#1c1c1c;transition:color .25s;letter-spacing: 0.2px}
.ticker-widget .post-title a:hover{color:$(title.hover)}
.ticker-widget .post-tag{position:static;float:left;margin:5px 10px 0 0}
.ticker-widget .owl-nav{position:absolute;top:0;right:0;width:52px;height:24px;z-index:5}
.ticker-widget .owl-nav .owl-prev{margin-top:3px}
#break-section .widget > .widget-title > h3:before {
    content: '';
    position: absolute;
    left: -10px;
    z-index: 0;
    bottom: -8px;
    border-top: 8px solid;
    border-top-color: #ec0000;
    border-right: 5px solid transparent;
    -webkit-transition: 400ms;
}
.ticker-widget .owl-nav .owl-next{margin:3px 0 0 4px}
#break-section .post-tag {display:none;background:#000}
@keyframes fadeInLeft {
from{opacity:0;transform:translate3d(-30px,0,0)}
to{opacity:1;transform:none}
}
from{opacity:1}
to{opacity:0;transform:translate3d(-30px,0,0)}
}
@keyframes fadeInRight {
from{opacity:0;transform:translate3d(30px,0,0)}
to{opacity:1;transform:none}
}
.fadeInRight{animation-name:fadeInRight}
@keyframes fadeOutRight {
from{opacity:1}
to{opacity:0;transform:translate3d(30px,0,0)}
}
.fadeOutRight{animation-name:fadeOutRight}
@keyframes fadeInUp {
from{opacity:0;transform:translate3d(0,30px,0)}
to{opacity:1;transform:none}
}
.fadeInUp{animation-name:fadeInUp}
@keyframes fadeOutUp {
from{opacity:1}
to{opacity:0;transform:translate3d(0,-30px,0)}
}
.fadeOutUp{animation-name:fadeOutUp}


.feat-col .feat-inner:before{content:'';display:block;position:absolute;width:100%;top:0;bottom:0;background:-moz-linear-gradient(top,rgba(0,0,0,0) 0,rgba(0,0,0,1) 65%,rgba(0,0,0,1) 100%);background:-webkit-linear-gradient(top,rgba(0,0,0,0) 0,rgba(0,0,0,1) 65%,rgba(0,0,0,1) 100%);background:linear-gradient(to bottom,rgba(0,0,0,0) 0,rgba(0,0,0,1) 65%,rgba(0,0,0,1) 100%);opacity:.6;z-index:2}
.feat-col li{position:relative;float:left;width:100%;overflow:hidden;margin:25px 0 0}
.feat-col .item-0{margin:0}
.feat-col .feat-inner{position:relative;float:left;width:100%;overflow:hidden}
.feat-col .post-image-link{position:relative;float:left;width:100px;height:80px;display:block;overflow:hidden;margin:0 12px 0 0}
.feat-col .feat-inner .post-image-link{width:100%;height:265px}
.feat-col .post-title{font-family:'Arimo',sans-serif;overflow:hidden;font-size:14px;font-weight:600;line-height:1.5em;margin:0 0 3px}
.feat-col .item-big .post-info{position:absolute;float:left;width:100%;z-index:2;bottom:0;padding:15px 20px;box-sizing:border-box}
